#include "../kelly-slaters-pro-surfer/KS/SRC/global.h"
#include "../kelly-slaters-pro-surfer/KS/SRC/entity.h"

entity_manager::~entity_manager()
{
  name_to_number_map::iterator mi;
  mi = name_to_number.begin();
  for(; mi != name_to_number.end(); ++mi )
  {
    delete[] (*mi).first.str;
  }
  erase( begin(), end() );
  name_to_number = name_to_number_map();
}
